-- Clinical Placements Database — full schema
--
-- Generated by introspecting the live Supabase database on 2026-07-15.
-- Running this against an empty Postgres database produces every table, index,
-- trigger and view the application queries. Structure only — see
-- docs/DATA_PIPELINE.md for loading the data.
--
-- Object inventory: 10 tables + 1 view.
--   layers, hrsa_sites, schools, post_secondary_schools, military_sites,
--   native_american_reserves, active_sites, county_population, state_economic,
--   notes, and the county_coverage view.
--
-- Keep this in sync when you change the database. A previous version of this
-- file defined only 7 of these objects, which meant the database could not be
-- rebuilt from a clone.

-- =============================================================================
-- TYPES AND FUNCTIONS
-- =============================================================================

-- schools.profession depends on this; create it before the tables.
CREATE TYPE profession_type AS ENUM ('PT', 'OT', 'PA');

-- Touches updated_at on write. Wired up as a BEFORE UPDATE trigger on the five
-- tables that are edited in place. The bulk-loaded tables (hrsa_sites,
-- active_sites) are truncated and reimported rather than updated, so they rely
-- on their column default instead.
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';

-- =============================================================================
-- LAYERS — map layer metadata, drives the sidebar toggles (10 rows)
-- =============================================================================

CREATE TABLE layers (
  id              SERIAL PRIMARY KEY,
  layer_key       VARCHAR(50)  NOT NULL UNIQUE,
  display_name    VARCHAR(100) NOT NULL,
  table_name      VARCHAR(100) NOT NULL,
  description     TEXT,
  icon            VARCHAR(50),
  color           CHAR(7),
  default_visible BOOLEAN   DEFAULT FALSE,
  sort_order      INTEGER   DEFAULT 0,
  created_at      TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_layers_layer_key ON layers (layer_key);

-- =============================================================================
-- HRSA_SITES — HRSA healthcare facilities (74,772 rows)
-- =============================================================================

CREATE TABLE hrsa_sites (
  id                       SERIAL PRIMARY KEY,
  site_name                TEXT,
  site_category            TEXT,
  state                    CHAR(2) NOT NULL,
  city                     TEXT,
  county_fips              CHAR(5),
  physician_ftes           NUMERIC(10,2) DEFAULT 0,
  physician_assistant_ftes NUMERIC(10,2) DEFAULT 0,
  num_beds                 INTEGER       DEFAULT 0,
  is_federally_funded_hc   BOOLEAN       DEFAULT FALSE,
  is_hospital_based        BOOLEAN       DEFAULT FALSE,
  site_type                TEXT,
  is_rural_health_clinic   BOOLEAN       DEFAULT FALSE,
  rural_status             TEXT,
  longitude                NUMERIC(11,7) NOT NULL,
  latitude                 NUMERIC(10,7) NOT NULL,
  source                   TEXT NOT NULL DEFAULT 'HRSA',
  created_at               TIMESTAMPTZ DEFAULT NOW(),
  updated_at               TIMESTAMPTZ DEFAULT NOW()
);

-- idx_hrsa_coords backs the viewport-bounds filter in /api/sites and
-- idx_hrsa_category backs the clinic-type filter. Both matter at this row count.
CREATE INDEX idx_hrsa_state        ON hrsa_sites (state);
CREATE INDEX idx_hrsa_coords       ON hrsa_sites (latitude, longitude);
CREATE INDEX idx_hrsa_category     ON hrsa_sites (site_category);
CREATE INDEX idx_hrsa_city         ON hrsa_sites (city);
CREATE INDEX idx_hrsa_fips         ON hrsa_sites (county_fips);
CREATE INDEX idx_hrsa_fqhc         ON hrsa_sites (is_federally_funded_hc);
CREATE INDEX idx_hrsa_name         ON hrsa_sites (site_name);
CREATE INDEX idx_hrsa_rural        ON hrsa_sites (is_rural_health_clinic);
CREATE INDEX idx_hrsa_rural_status ON hrsa_sites (rural_status);

-- =============================================================================
-- SCHOOLS — PT/OT/PA programs (858 rows across 655 institutions)
-- =============================================================================
-- One row per PROGRAM, not per institution: a university offering PT, OT and PA
-- occupies three rows sharing an institution_name. Group by institution before
-- display — /api/sites does this to produce one map marker per campus.
--
-- There are no outcome columns (graduation / licensure pass / employment
-- rates). That data was never collected. See docs/DATABASE.md.

CREATE TABLE schools (
  id                   SERIAL PRIMARY KEY,
  program_row_id       INTEGER,
  institution_name     VARCHAR(300) NOT NULL,
  campus_name          VARCHAR(200),
  state                CHAR(2) NOT NULL,
  profession           profession_type NOT NULL,
  program_name         VARCHAR(200),
  accreditation_body   VARCHAR(20),
  accreditation_status VARCHAR(200),
  address              VARCHAR(500),
  longitude            NUMERIC(11,7),
  latitude             NUMERIC(10,7),
  source               VARCHAR(50),
  created_at           TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at           TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_schools_state            ON schools (state);
CREATE INDEX idx_schools_profession       ON schools (profession);
CREATE INDEX idx_schools_state_profession ON schools (state, profession);
CREATE INDEX idx_schools_coords           ON schools (latitude, longitude);
CREATE INDEX idx_schools_name             ON schools (institution_name);

CREATE TRIGGER update_schools_updated_at BEFORE UPDATE ON schools
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- =============================================================================
-- POST_SECONDARY_SCHOOLS — all US post-secondary institutions (6,812 rows)
-- =============================================================================

CREATE TABLE post_secondary_schools (
  id               SERIAL PRIMARY KEY,
  original_id      INTEGER,
  institution_name VARCHAR(300) NOT NULL,
  state            CHAR(2) NOT NULL,
  latitude         NUMERIC(10,7),
  longitude        NUMERIC(11,7),
  source           VARCHAR(50),
  created_at       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at       TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_post_secondary_state  ON post_secondary_schools (state);
CREATE INDEX idx_post_secondary_coords ON post_secondary_schools (latitude, longitude);
CREATE INDEX idx_post_secondary_name   ON post_secondary_schools (institution_name);

CREATE TRIGGER update_post_secondary_updated_at BEFORE UPDATE ON post_secondary_schools
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- =============================================================================
-- MILITARY_SITES — US military installations (824 rows)
-- =============================================================================

CREATE TABLE military_sites (
  id         SERIAL PRIMARY KEY,
  name       VARCHAR(300) NOT NULL,
  state      CHAR(2) NOT NULL,
  component  VARCHAR(50),
  longitude  NUMERIC(11,7),
  latitude   NUMERIC(10,7),
  source     VARCHAR(50),
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_military_state  ON military_sites (state);
CREATE INDEX idx_military_coords ON military_sites (latitude, longitude);
CREATE INDEX idx_military_name   ON military_sites (name);

CREATE TRIGGER update_military_updated_at BEFORE UPDATE ON military_sites
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- =============================================================================
-- NATIVE_AMERICAN_RESERVES — tribal reservation locations (693 rows)
